import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"25、【無妄】 震下乾上","description":"周易口訣義 - 25、【無妄】 震下乾上","frontmatter":{"title":"25、【無妄】 震下乾上","description":"周易口訣義 - 25、【無妄】 震下乾上"},"headers":[],"relativePath":"classics/koujueyi/027.md","filePath":"classics/koujueyi/027.md"}'),r={name:"classics/koujueyi/027.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_25、【無妄】-震下乾上" tabindex="-1">25、【無妄】 震下乾上 <a class="header-anchor" href="#_25、【無妄】-震下乾上" aria-label="Permalink to “25、【無妄】 震下乾上”">​</a></h1><p>彖曰：無妄，剛自外來而為主於內，動而健，剛中而應，大亨以正，天之命也。「其匪正有眚，不利有攸往」，無妄之往，何之矣？天命不祐，行矣哉！</p><p>象曰：天下雷行，物與無妄。先王以茂對時育萬物。</p><p>初九：無妄，往吉。象曰：「無妄」之往，得志也。</p><p>六二：不耕穫，不菑畬，則利有攸往。</p><p>象曰：「不耕穫」，未富也。</p><p>六三：無妄之災，或繫之牛，行人之得，邑人之災。</p><p>象曰：行人得牛，邑人災也。</p><p>九四：可貞，無咎。</p><p>象曰：「可貞無咎」，固有之也。</p><p>九五：無妄之疾，勿藥有喜。</p><p>象曰：「無妄」之藥，不可試也。</p><p>上九：無妄行有眚，無攸利。</p><p>象曰：「無妄」之行，窮之災也。</p><p>無（四庫全書標明，摘錄時缺豫、隨、無妄、大壯、晉、睽、蹇、解、中孚八卦）</p>',15)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
